import React, { useEffect, useState } from 'react';
import { ShoppingCart, Info, Flower, Plus } from 'lucide-react';
import { api } from "../api/index";
import './/ShopPage.scss';
import ImageModal from './components/ImageModal';

const localImageModal = ({imageUrl,onClose}) => {
    if (!imageUrl) return null;
    return (
        <div 
            onClick={onClose}
            style={{
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                backgroundColor: 'rgba(0, 0, 0, 0.9)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 99999, // Огромный z-index
                padding: '20px',
                cursor: 'zoom-out'
            }}
        >
            <button 
                onClick={onClose}
                style={{
                    position: 'absolute',
                    top: '30px',
                    right: '30px',
                    background: 'white',
                    border: 'none',
                    borderRadius: '50%',
                    width: '50px',
                    height: '50px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    cursor: 'pointer',
                    boxShadow: '0 0 20px rgba(0,0,0,0.5)'
                }}
            >
                <X size={30} color="black" />
            </button>
            <img 
                src={imageUrl} 
                alt="Full size" 
                onClick={(e) => e.stopPropagation()}
                style={{
                    maxWidth: '95vw',
                    maxHeight: '95vh',
                    objectFit: 'contain',
                    borderRadius: '10px',
                    boxShadow: '0 0 40px rgba(0,0,0,0.8)',
                    cursor: 'default'
                }}
            />
        </div>
    );
};

const ShopPage = () => {
    const [flowers, setFlowers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const [selectedImage,  setSelectedImage ] = useState(null);

    useEffect(() => {
    const loadFlowers = async () => {
      try {
        setLoading(true);
        const data = await api.getFlowers();
        setFlowers(data);
     } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
            loadFlowers();
  }, []); // Пустые скобки [] значат: выполнить 1 раз при открытии страницы



  if (error) return (
    <div className="page" style={{textAlign:'center', padding:'50px'}}>
      <h2 style={{color: '#ef4444'}}>Ошибка: {error}</h2>
      <p>Убедитесь, что сервер бэкенда запущен</p>
    </div>
  );

  return (
    <div className="page">
      <header className="header">
        <div className="header__inner">
          <div className="brand">FLOWER STORE</div>
          <button className="btn btn--primary">
            <ShoppingCart size={18} /> Корзина
          </button>
        </div>
      </header>

      <main className="container">
        <div className="toolbar">
          <h1 className="title">Каталог цветов</h1>
          <span className="badge">{flowers.length} в наличии</span>
        </div>

        <div className="shopGrid">
          {flowers.map((item) => (
            <div key={item.id || item._id} className="productCard">
              <img 
                src={item.image.startsWith('http') ? item.image : `http://localhost:5001${item.image}`} 
                alt={item.name} 
                className="productCard__image" 
              />
              <div className="productCard__content">
                <div style={{display:'flex', justifyContent:'space-between'}}>
                  <h3 className="productCard__title">{item.name}</h3>
                  <span className="productCard__price">{item.price}₽</span>
                </div>
                <p style={{fontSize:'14px', opacity:0.7, margin:'10px 0'}}>
                  {item.description}
                </p>
                <button className="btn btn--primary" style={{marginTop:'auto'}}>
                  Купить
                </button>
              </div>
            </div>
          ))}
        </div>
      </main>
          <ImageModal
          imageUrl={selectedImage}
          onClose={() => setSelectedImage(null)}
          />
    </div>
  );
};

export default ShopPage;
